+import { type SQL, sql, type SQLWrapper } from '../sql.ts';
+
+export type WindowFrameBoundary = 'unbounded preceding' | 'current row' | 'unbounded following' | { type: 'preceding' | 'following'; value: number };
+export const unboundedPreceding: WindowFrameBoundary = 'unbounded preceding';
+export const currentRow: WindowFrameBoundary = 'current row';
+export const unboundedFollowing: WindowFrameBoundary = 'unbounded following';
+
+function offsetBoundary(type: 'preceding' | 'following', value: number): WindowFrameBoundary {
+	if (!Number.isInteger(value) || value < 0) throw new Error(`${type}() requires a non-negative integer; received ${value}`);
+	return { type, value };
+}
+
+export function preceding(value: number): WindowFrameBoundary { return offsetBoundary('preceding', value); }
+export function following(value: number): WindowFrameBoundary { return offsetBoundary('following', value); }
+
+export interface WindowFrame { type: 'rows' | 'range'; from: WindowFrameBoundary; to: WindowFrameBoundary }
+export interface WindowSpec { partitionBy?: SQLWrapper | SQLWrapper[]; orderBy?: SQLWrapper | SQLWrapper[]; frame?: WindowFrame }
+
+const boundaryOrder = (boundary: WindowFrameBoundary): number => boundary === unboundedPreceding ? -Infinity : boundary === unboundedFollowing ? Infinity : boundary === currentRow ? 0 : boundary.type === 'preceding' ? -boundary.value : boundary.value;
+function frame(type: WindowFrame['type'], spec: Omit<WindowFrame, 'type'>): WindowFrame {
+	if (boundaryOrder(spec.from) > boundaryOrder(spec.to)) throw new Error('Window frame "from" boundary must not be after "to" boundary');
+	return { type, ...spec };
+}
+export function rows(spec: Omit<WindowFrame, 'type'>): WindowFrame { return frame('rows', spec); }
+export function range(spec: Omit<WindowFrame, 'type'>): WindowFrame { return frame('range', spec); }
+
+function renderBoundary(boundary: WindowFrameBoundary): SQL {
+	return typeof boundary === 'string' ? sql.raw(boundary) : sql.raw(`${boundary.value} ${boundary.type}`);
+}
+export function buildWindowSpec(spec: WindowSpec): SQL {
+	const partitionBy = spec.partitionBy ? (Array.isArray(spec.partitionBy) ? spec.partitionBy : [spec.partitionBy]) : [];
+	const orderBy = spec.orderBy ? (Array.isArray(spec.orderBy) ? spec.orderBy : [spec.orderBy]) : [];
+	const frameSql = spec.frame ? sql` ${sql.raw(spec.frame.type)} between ${renderBoundary(spec.frame.from)} and ${renderBoundary(spec.frame.to)}` : undefined;
+	return sql`${partitionBy.length ? sql`partition by ${sql.join(partitionBy, sql`, `)}` : undefined}${partitionBy.length && orderBy.length ? sql` ` : undefined}${orderBy.length ? sql`order by ${sql.join(orderBy, sql`, `)}` : undefined}${frameSql}`;
+}
+export interface WindowDefinition { name: string; spec: WindowSpec }
+export function buildWindowDefinitions(windows: WindowDefinition[] | undefined): SQL | undefined {
+	return windows?.length ? sql` window ${sql.join(windows.map(({ name, spec }) => sql`${sql.identifier(name)} as (${buildWindowSpec(spec)})`), sql`, `)}` : undefined;
+}
+
+export class WindowFunction<T> implements SQLWrapper {
+	constructor(private readonly expression: SQL<T>) {}
+	getSQL(): SQL<T> { return this.expression; }
+	over(spec: WindowSpec | string = {}): SQL<T> {
+		return typeof spec === 'string' ? sql`${this.expression} over ${sql.identifier(spec)}` : sql`${this.expression} over (${buildWindowSpec(spec)})`;
+	}
+}
+function fn<T>(name: string, args: SQLWrapper[] = []): WindowFunction<T> { return new WindowFunction(sql`${sql.raw(name)}(${sql.join(args, sql`, `)})`); }
+function integer(name: string, value: number): SQLWrapper {
+	if (!Number.isInteger(value) || value <= 0) throw new Error(`${name}() requires a positive integer; received ${value}`);
+	return sql.raw(String(value));
+}
