+const dialect = new PgDialect();
+const toQuery = (expression: { getSQL(): ReturnType<typeof sql> }) => dialect.sqlToQuery(expression.getSQL());
+
+test('window functions render inline specs and positional arguments without parameters', () => {
+	expect(toQuery(rowNumber().over())).toEqual({ sql: 'row_number() over ()', params: [] });
